  const m=s.match(/^([^A-Za-zÀ-ÿœŒ0-9«(]*)(.*?)([^A-Za-zÀ-ÿœŒ0-9»)]*)$/u);
  if(m&&(m[1]||m[3])){const a=m[1],core=m[2],z=m[3];
    const cc=core&&core[0]!==core[0].toUpperCase()?core[0].toUpperCase()+core.slice(1):null;
    for(let i=0;i<=z.length;i++){r=C.D.get(core+z.slice(0,i));if(r!=null)return a+r+z.slice(i);
      if(cc){r=C.D.get(cc+z.slice(0,i));if(r!=null)return a+r[0].toLowerCase()+r.slice(1)+z.slice(i)}
      if(a){r=C.D.get(a+core+z.slice(0,i));if(r!=null)return r+z.slice(i)}}}
  // minuscule en tête (« plus aucun plante à fleurs… ») : on essaie avec une majuscule
  const c0=s[0];if(c0!==c0.toUpperCase()){r=C.D.get(c0.toUpperCase()+s.slice(1));if(r!=null)return r[0].toLowerCase()+r.slice(1)}
