  const pre=m&&m[1]?m[1]:'',cands=pre?[[s,''],[s.slice(pre.length),pre]]:[[s,'']];
  if(depth<3)for(const [x,a] of cands)for(const t of C.T){const g=x.match(t.re);if(!g)continue;
    if(typeof t.v==='function')return a+t.v(...g);
    const caps=g.slice(1).map(y=>langCore(langNorm(y),depth+1));let i=0;
    return a+t.v.replace(/\{(\d*)\}/g,(_,n)=>n===''?(caps[i++]??''):(caps[+n]??''))}
