  if(depth<3){const ph=s.split(/(?<=[.!?…]) (?=[^a-zà-ÿ])/u);if(ph.length>1){const tp=ph.map(x=>langCore(x,depth+1));if(tp.some((x,i)=>x!==ph[i]))return tp.join(' ')}}
