  const k=s.indexOf(' : ');
  if(k>0&&depth<3){const a=langCore(s.slice(0,k),depth+1),b=langCore(s.slice(k+3),depth+1);if(a!==s.slice(0,k)||b!==s.slice(k+3))return a+': '+b}
